import{_ as a,c as o,o as t,ag as r}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"Privacy Choices","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy-choices.md","filePath":"guide/privacy-choices.md","lastUpdated":1794822481000}'),i={name:"guide/privacy-choices.md"};function s(l,e,n,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-choices" tabindex="-1">Privacy Choices <a class="header-anchor" href="#privacy-choices" aria-label="Permalink to &quot;Privacy Choices&quot;">​</a></h1><p>nPlyr is a local-first application. Because your data stays on your device, we do not collect, sell, or share any personal information.</p><h2 id="data-we-hold-locally" tabindex="-1">Data We Hold Locally <a class="header-anchor" href="#data-we-hold-locally" aria-label="Permalink to &quot;Data We Hold Locally&quot;">​</a></h2><p>nPlyr stores all data locally on your device:</p><ul><li>Watch history, bookmarks and downloads</li><li>App preferences and theming</li><li>Mini-program variables (in local storage, only from rules you import)</li><li>Debug logs (if enabled)</li></ul><p>None of this data is uploaded to any server by the app itself.</p><h2 id="network-is-user-directed" tabindex="-1">Network Is User-Directed <a class="header-anchor" href="#network-is-user-directed" aria-label="Permalink to &quot;Network Is User-Directed&quot;">​</a></h2><p>nPlyr uses the network only when you stream, download, browse or run a mini-program you chose. There are no cloud AI features and no account, so there is nothing to opt in or out of — the app simply does not send your data to us.</p><h2 id="your-rights" tabindex="-1">Your Rights <a class="header-anchor" href="#your-rights" aria-label="Permalink to &quot;Your Rights&quot;">​</a></h2><p>Since nPlyr does not collect or store personal data on our servers, there is no personal data for us to access, delete, or transfer. You can manage or remove all of your data at any time:</p><ul><li>On macOS: <strong>Settings → Advanced → Reset</strong> clears local app data; uninstalling the app removes its container.</li><li>On iOS / iPadOS: <strong>Settings → Advanced → Reset</strong> clears local app data; deleting the app removes its data.</li></ul><p>No command line or external tool is required.</p><h2 id="do-not-sell" tabindex="-1">Do Not Sell <a class="header-anchor" href="#do-not-sell" aria-label="Permalink to &quot;Do Not Sell&quot;">​</a></h2><p>nPlyr does not sell any personal information. We do not use third-party analytics, advertising, or tracking services of any kind.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>If you have questions about privacy choices, open an issue at: <code>https://github.com/nPlyr/nPlyr-site/issues</code></p>',16)])])}const y=a(i,[["render",s]]);export{u as __pageData,y as default};
